nta.declaration:
urgent chan dummy;
urgent chan start;
chan finish;

// ——————————————————————————————
// Model parameters
// ——————————————————————————————
const int NUM_ACTORS = 13;
const int NUM_EDGES = 26;
const int MAX_TOKENS = 1;

// ——————————————————————————————
// Typedefs for indices
// ——————————————————————————————
typedef int[1, NUM_ACTORS] actor_t;
typedef int[1, NUM_EDGES] edges_t;
typedef int[0, MAX_TOKENS-1] index_t;

// ——————————————————————————————
// Edge metadata (global)
// ——————————————————————————————
typedef struct {
  actor_t from;   // source actor
  actor_t to;     // destination actor
} edge_t;

edge_t edges[edges_t] ={
  { 1, 2 }, // A -> B_start
  { 1, 3 }, // A -> D_start
  { 2, 4 }, // B_start -> B
  { 5, 6 }, // C_start -> C
  { 3, 7 }, // D_start -> D
  { 8, 9 }, // E_start -> E
  { 10, 11 }, // F_start -> F
  { 12, 13 }, // G_start -> G
  { 4, 2 }, // B -> B_start
  { 6, 5 }, // C -> C_start
  { 7, 3 }, // D -> D_start
  { 9, 8 }, // E -> E_start
  { 11, 10 }, // F -> F_start
  { 13, 12 }, // G -> G_start
  { 4, 5 }, // B -> C_start
  { 7, 8 }, // D -> E_start
  { 9, 10 }, // E -> F_start
  { 11, 5 }, // F -> C_start
  { 6, 12 }, // C -> G_start
  { 5, 2 }, // C_start -> B_start
  { 8, 3 }, // E_start -> D_start
  { 10, 8 }, // F_start -> E_start
  { 5, 10 }, // C_start -> F_start
  { 12, 5 }, // G_start -> C_start
  { 2, 1 }, // B_start -> A
  { 3, 1 } // D_start -> A
};


// ——————————————————————————————————————————
// Token buffers
// ——————————————————————————————————————————
// edge_token[e][slot]
// slot ∈ {0} only
bool edge_token[NUM_EDGES+1][MAX_TOKENS] =  {
  /* unused index 0 */ { false },
  /* A → B_start */     { true },
  /* A → D_start */     { true },
  /* B_start → B */     { false },
  /* C_start → C */     { false },
  /* D_start → D */     { false },
  /* E_start → E */     { false },
  /* F_start → F */     { false },
  /* G_start → G */     { false },
  /* B → B_start */     { true },
  /* C → C_start */     { true },
  /* D → D_start */     { true },
  /* E → E_start */     { true },
  /* F → F_start */     { true },
  /* G → G_start */     { true },
  /* B → C_start */     { true },
  /* D → E_start */     { true},
  /* E → F_start */     { true },
  /* F → C_start */     { true },
  /* C → G_start */     { true },
  /* C_start → B_start */ { true },
  /* E_start → D_start */ { true },
  /* F_start → E_start */ { true },
  /* C_start → F_start */ { true },
  /* G_start → C_start */ { true },
  /* B_start → A */     { true },
  /* D_start → A */     { true }
};

// ——————————————————————————————————————————
// Actor ready-flags
// ——————————————————————————————————————————
// actor_ready[a][slot] = true iff all incoming edges into a carry a token
bool actor_ready[NUM_ACTORS+1][MAX_TOKENS] = {
  /* unused actor 0 */  { false },
  /* actor 1 (A) */     { true },
  /* actor 2 (B_start) */ { false },
  /* actor 3 (D_start) */ { false },
  /* actor 4 (B) */     { false },
  /* actor 5 (C_start) */ { false },
  /* actor 6 (C) */     { false },
  /* actor 7 (D) */     { false },
  /* actor 8 (E_start) */ { false },
  /* actor 9 (E) */     { false },
  /* actor 10 (F_start) */ { false },
  /* actor 11 (F) */    { false },
  /* actor 12 (G_start) */ { false },
  /* actor 13 (G) */    { false }
};


// ——————————————————————————————
// Query: has actor `act` all inputs at slot `idx`?
// (i.e. is it *not* empty?)
// ——————————————————————————————
bool empty(actor_t act, index_t idx) {
  return not actor_ready[act][idx];
}

// ——————————————————————————————
// Produce on *all* outgoing edges of `act`, then update downstream flags
// ——————————————————————————————
void produce_actor(actor_t act, index_t idx) {
  actor_t dst;
  bool all_in;
  for (e : edges_t) {
    if (edges[e].from == act) {
      // place the token
      edge_token[e][idx] = true;
      // recompute readiness for the destination actor
      dst = edges[e].to;
      all_in = true;
      for (er : edges_t) {
        if (edges[er].to == dst && not edge_token[er][idx]) {
          all_in = false;
        }
      }
      actor_ready[dst][idx] = all_in;
    }
  }
}


// ——————————————————————————————
// Consume incoming token for `act`, then update its own flag
// ——————————————————————————————
void consume_actor(actor_t act, index_t idx) {
  // Local variables must be declared up front
  bool      all_in;
  index_t   next;

  // clear our own readiness at the current slot
  actor_ready[act][idx] = false;

  // clear tokens on all incoming edges at current slot
  for (e : edges_t) {
    if (edges[e].to == act) {
      edge_token[e][idx] = false;
    }
  }

  // compute the next buffer slot (circular)
  next = (idx + 1) % MAX_TOKENS;

  // check if *all* incoming edges have a token at 'next'
  all_in = true;
  for (er : edges_t) {
    if (edges[er].to == act && not edge_token[er][next]) {
      all_in = false;
    }
  }

  // u pdate readiness for the next slot
  actor_ready[act][next] = all_in;
}

template.declaration:
clock r;
int m = -1;
int n = 0;

nta.system:
// Actor ID definitions
actor_t id1 = 1; // A
actor_t id2 = 2; // B_start
actor_t id3 = 3; // D_start
actor_t id4 = 4; // B
actor_t id5 = 5; // C_start
actor_t id6 = 6; // C
actor_t id7 = 7; // D
actor_t id8 = 8; // E_start
actor_t id9 = 9; // E
actor_t id10 = 10; // F_start
actor_t id11 = 11; // F
actor_t id12 = 12; // G_start
actor_t id13 = 13; // G

// WCET ranges per actor
const int LOW_1 = 1585, HIGH_1 = 1585; // A
const int LOW_2 = 0, HIGH_2 = 0; // B_start
const int LOW_3 = 0, HIGH_3 = 0; // D_start
const int LOW_4 = 0, HIGH_4 = 217; // B
const int LOW_5 = 0, HIGH_5 = 0; // C_start
const int LOW_6 = 2382, HIGH_6 = 2382; // C
const int LOW_7 = 0, HIGH_7 = 524; // D
const int LOW_8 = 0, HIGH_8 = 0; // E_start
const int LOW_9 = 90, HIGH_9 = 90; // E
const int LOW_10 = 0, HIGH_10 = 0; // F_start
const int LOW_11 = 276, HIGH_11 = 276; // F
const int LOW_12 = 0, HIGH_12 = 0; // G_start
const int LOW_13 = 247, HIGH_13 = 247; // G

// Actor instantiations
actorA = ActorStart(id1, LOW_1, HIGH_1);
actorBs = Actor(id2, LOW_2, HIGH_2);
actorDs = Actor(id3, LOW_3, HIGH_3);
actorB = Actor(id4, LOW_4, HIGH_4);
actorCs = Actor(id5, LOW_5, HIGH_5);
actorC = Actor(id6, LOW_6, HIGH_6);
actorD = Actor(id7, LOW_7, HIGH_7);
actorEs = Actor(id8, LOW_8, HIGH_8);
actorE = Actor(id9, LOW_9, HIGH_9);
actorFs = Actor(id10, LOW_10, HIGH_10);
actorF = Actor(id11, LOW_11, HIGH_11);
actorGs = Actor(id12, LOW_12, HIGH_12);
actorG = ActorFinish(id13, LOW_13, HIGH_13);

system actorA, actorBs, actorDs, actorB, actorCs, actorC, actorD, actorEs, actorE, actorFs, actorF, actorGs, actorG, Dummy, Timer;
